// App（FCM）推送：Android/iOS 原生通知——App 閂咗／鎖屏都收到新單
// 註冊流程：權限 → register → 攞 token → 上報 server（POST /api/push/fcm-token）
// 注意：插件必須 static import（dynamic import 喺 Capacitor WebView 會全啞聲——2.0.92 教訓）
import { PushNotifications } from '@capacitor/push-notifications';
import { getToken } from './api';

export function isNativeApp(): boolean {
  try {
    const c = (window as any).Capacitor;
    return !!(c && c.isNativePlatform && c.isNativePlatform());
  } catch {
    return false;
  }
}

export async function registerFcmPush(): Promise<{ status: 'ok' | 'skipped' | 'denied' | 'error'; detail?: string }> {
  try {
    if (!isNativeApp()) return { status: 'skipped', detail: '非 App 環境（網頁版用 Web Push）' };

    // 1. 權限
    let perm: { receive?: string } = {};
    try {
      perm = await PushNotifications.requestPermissions();
    } catch {
      // 部分 Android 版本 requestPermissions 會直接 resolve，唔會 throw；throw 就當已允許再試
      perm = { receive: 'granted' };
    }
    if (perm.receive !== 'granted') {
      return { status: 'denied', detail: '用戶未允許通知權限' };
    }

    // 2. 註冊（攞 FCM token）
    await PushNotifications.register();

    // 3. 等 registration 事件回傳 token，然後上報 server
    return await new Promise((resolve) => {
      let done = false;
      const finish = (r: { status: 'ok' | 'error'; detail?: string }) => {
        if (!done) { done = true; resolve(r); }
      };
      PushNotifications.addListener('registration', async (tokenInfo: any) => {
        try {
          const token = tokenInfo?.value;
          if (!token) { finish({ status: 'error', detail: 'FCM token 係空' }); return; }
          const res = await fetch('/api/push/fcm-token', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${getToken()}`,
            },
            body: JSON.stringify({ token, platform: 'android' }),
          });
          if (res.ok) finish({ status: 'ok', detail: token });
          else finish({ status: 'error', detail: '上報 token 失敗 (' + res.status + ')' });
        } catch (e: any) {
          finish({ status: 'error', detail: e?.message || '上報 token 失敗' });
        }
      });
      PushNotifications.addListener('registrationError', (err: any) => {
        finish({ status: 'error', detail: err?.error || 'FCM 註冊失敗（可能未配置 google-services.json）' });
      });
      // 兜底：12 秒冇回調就唔等（唔會卡死登入流程）
      setTimeout(() => finish({ status: 'error', detail: 'FCM 註冊超時' }), 12000);
    });
  } catch (e: any) {
    return { status: 'error', detail: e?.message || 'FCM 註冊失敗' };
  }
}
